from __future__ import annotations

from typing import Tuple, Union

from . import dmSDK as _cx

DEFAULT_TIMEOUT_MS = 3000


def parse_detect_enabled(value: Union[str, bool]) -> bool:
    if isinstance(value, bool):
        return value

    normalized = str(value).strip().lower()
    if normalized in {"1", "true", "yes", "on", "enable", "enabled"}:
        return True
    if normalized in {"0", "false", "flase", "no", "off", "disable", "disabled"}:
        return False
    raise ValueError(f"invalid detect switch value: {value}")


def set_detect_enabled(value: Union[str, bool]) -> Tuple[bool, str]:
    enabled = parse_detect_enabled(value)
    ok, message = _cx.setDetectEnabled(bool(enabled))
    return bool(ok), str(message)


def init_sensor_cache(serial: str, timeout_ms: int = DEFAULT_TIMEOUT_MS) -> Tuple[bool, str]:
    ok, message = _cx.initSensorCache(str(serial), int(timeout_ms))
    return bool(ok), str(message)
